mapper.select:
SELECT id, title, pay_type, price, vip_free, status, create_time, update_time
FROM sys_article_pay_rule


        AND title LIKE CONCAT('%', #{query.title}, '%')


        AND pay_type = #{query.payType}


        AND vip_free = #{query.vipFree}


        AND status = #{query.status}


ORDER BY create_time DESC
